SELECT sales_center_id, sales_center_name, remark1, SUM(performance_goal) as sum1, SUM(visit_goal) as sum2, SUM(achieved_performance_goal) as sum3, SUM(achieved_visit_goal) as sum4 FROM dc_salescenter_performance_task WHERE 1=1
AND sales_center_id = #{salesCenterId}
AND remark1 = #{city}
AND task_month = #{taskMonth}
AND task_month = DATE_FORMAT(CURRENT_DATE(), '%Y%m')
GROUP BY sales_center_id, sales_center_name, remark1

SELECT sales_center_id, sales_center_name, remark1, SUM(performance_goal) as sum1, SUM(visit_goal) as sum2, SUM(achieved_performance_goal) as sum3, SUM(achieved_visit_goal) as sum4 FROM dc_salescenter_performance_task WHERE 1=1
AND sales_center_id = #{salesCenterId}
AND remark1 = #{city}
AND LEFT(task_month, 4) = #{taskYear}
AND LEFT(task_month, 4) = YEAR(CURRENT_DATE())
GROUP BY sales_center_id, sales_center_name, remark1
